create or replace function api.app_guard() returns trigger language plpgsql security definer set search_path to 'api','pg_temp' as $f$
declare o int; n int; lim numeric; appr numeric;
begin
  select ord into n from api.status where id=new.status_id;
  if tg_op='INSERT' then
    if n is distinct from 1 then raise exception 'новая заявка создаётся в статусе Черновик' using errcode='23514'; end if;
  elsif new.status_id is distinct from old.status_id then
    select ord into o from api.status where id=old.status_id;
    if not ((o=1 and n=2) or (o=2 and n=3) or (o=3 and n in (4,5))) then
      raise exception 'недопустимый переход статуса' using errcode='23514'; end if;
  end if;
  if n in (4,5) and coalesce(btrim(new.verdict),'')='' then
    raise exception 'нужно заключение эксперта' using errcode='23514'; end if;
  if n=4 then
    select funding_limit into lim from api.company where id=new.company_id for update;
    select coalesce(sum(amount),0) into appr from api.application
      where company_id=new.company_id and status_id=20003 and id is distinct from new.id;
    if lim is null or new.amount > lim - appr then
      raise exception 'сумма превышает остаток лимита компании (лимит %, уже одобрено %)', lim, appr using errcode='23514'; end if;
  end if;
  return new;
end $f$;
select c.id, c.funding_limit, (select coalesce(sum(amount),0) from api.application a where a.company_id=c.id and status_id=20003) appr from api.company c;
select a.id,a.company_id,a.status_id,a.amount,a.verdict from api.application a order by id;
select login,role,company_id from api.app_user;

